21	namespace hybrid::gdbstub
22	{
23	
24	inline auto compute_checksum(std::string_view body) -> uint8_t
25	{
26	  unsigned sum = 0;
27	  for (char c : body) sum += static_cast<unsigned char>(c);
28	  return static_cast<uint8_t>(sum & 0xFFu);
29	}
30	
31	namespace detail
32	{
33	
34	inline auto hex_nybble(unsigned v) -> char
35	{
36	  return static_cast<char>(v < 10 ? '0' + v : 'a' + (v - 10));
37	}
38	
39	inline void append_hex_byte(std::string& out, uint8_t b)
40	{
41	  out.push_back(hex_nybble((b >> 4) & 0xFu));
42	  out.push_back(hex_nybble(b & 0xFu));
43	}
44	
45	inline auto from_hex(char c) -> std::optional<unsigned>
46	{
47	  if (c >= '0' && c <= '9') return static_cast<unsigned>(c - '0');
48	  if (c >= 'a' && c <= 'f') return static_cast<unsigned>(c - 'a' + 10);
49	  if (c >= 'A' && c <= 'F') return static_cast<unsigned>(c - 'A' + 10);
50	  return std::nullopt;
51	}
52	
53	}  // namespace detail
54	
55	inline auto encode_packet(std::string_view body) -> std::string
56	{
57	  std::string out;
58	  out.reserve(body.size() + 4);
59	  out.push_back('$');
60	  out.append(body);
61	  out.push_back('#');
62	  detail::append_hex_byte(out, compute_checksum(body));
63	  return out;
64	}
65	
66	namespace detail
67	{
68	
69	// Emits a register number in the minimum number of hex nibbles. CSR-feature
70	// regnums in QEMU's RISC-V gdbstub run up to ~3000, so 2-nibble encodings
71	// silently truncate and clobber a low-numbered register.
72	inline void append_reg_num_hex(std::string& out, unsigned reg_num)
73	{
74	  if (reg_num == 0) {
75	    out.push_back('0');
76	    return;
77	  }
78	  unsigned shift = 0;
79	  unsigned tmp   = reg_num;
80	  while (tmp >= 16) { tmp >>= 4; shift += 4; }
81	  while (true) {
82	    out.push_back(hex_nybble((reg_num >> shift) & 0xFu));
83	    if (shift == 0) break;
84	    shift -= 4;
85	  }
86	}
87	
88	}  // namespace detail
89	
90	// `P<reg>=<bytes-le-hex>` body for arbitrary-width payloads (e.g. vector
91	// regs whose width = vlenb bytes). No $...# framing.
92	inline auto encode_p_body_bytes(unsigned reg_num,
93	                                const uint8_t* bytes,
94	                                std::size_t n) -> std::string
95	{
96	  std::string body;
97	  body.reserve(4 + n * 2);
98	  body.push_back('P');
99	  detail::append_reg_num_hex(body, reg_num);
100	  body.push_back('=');
101	  for (std::size_t i = 0; i < n; ++i) detail::append_hex_byte(body, bytes[i]);
102	  return body;
103	}
104	
105	// Body of a `P<reg-hex>=<value-bytes-le-hex>` packet. reg is the GDB register
106	// number (0..31 for GPR, 32 for pc on RV64, 3-digit regnums for CSR-feature
107	// entries). The scalar value is sent as its 8 little-endian bytes.
108	inline auto encode_p_body(unsigned reg_num, uint64_t value) -> std::string
109	{
110	  std::array<uint8_t, 8> le{};
111	  for (auto& b : le) {
112	    b = static_cast<uint8_t>(value & 0xFFu);
113	    value >>= 8;
114	  }
115	  return encode_p_body_bytes(reg_num, le.data(), le.size());
116	}
117	
118	inline auto encode_p_packet(unsigned reg_num, uint64_t value) -> std::string
119	{
120	  return encode_packet(encode_p_body(reg_num, value));
121	}
122	
123	inline auto encode_continue() -> std::string
124	{
125	  return encode_packet("c");
126	}
127	
128	// Parses one $body#cksum frame and returns the body iff the checksum matches.
129	inline auto parse_packet(std::string_view raw) -> std::optional<std::string>
130	{
131	  if (raw.size() < 4 || raw.front() != '$') return std::nullopt;
132	  const auto hash = raw.find('#');
133	  if (hash == std::string_view::npos) return std::nullopt;
134	  if (raw.size() < hash + 3) return std::nullopt;
135	
136	  const auto body = raw.substr(1, hash - 1);
137	  const auto cs_hi = detail::from_hex(raw[hash + 1]);
138	  const auto cs_lo = detail::from_hex(raw[hash + 2]);
139	  if (!cs_hi || !cs_lo) return std::nullopt;
140	
141	  const auto expected = static_cast<uint8_t>((*cs_hi << 4) | *cs_lo);
142	  if (expected != compute_checksum(body)) return std::nullopt;
143	
144	  return std::string{body};
145	}
146	
147	// Map from gdb register name (e.g. "mstatus", "ft0") -> packet register
148	// number used in `P<reg>=...` and `g`/`G`. Built by walking target.xml +
149	// each `<xi:include>` annex.
150	class RegMap
151	{
152	public:
153	  void insert(std::string name, unsigned reg_num)
154	  {
155	    table_.emplace(std::move(name), reg_num);
156	  }
157	
158	  auto find(const std::string& name) const -> std::optional<unsigned>
159	  {
160	    const auto it = table_.find(name);
161	    if (it == table_.end()) return std::nullopt;
162	    return it->second;
163	  }
164	
165	  auto size() const -> std::size_t { return table_.size(); }
166	
167	private:
168	  std::unordered_map<std::string, unsigned> table_;
169	};
170	
171	// Extracts the value of an attribute from one XML element start tag.
172	// `tag_start` points at the '<' of the tag; the search runs until the
173	// matching '>' or the end of the string.
174	inline auto extract_attr(std::string_view xml,
175	                         std::size_t tag_start,
176	                         std::string_view name) -> std::optional<std::string>
177	{
178	  const auto end = xml.find('>', tag_start);
179	  if (end == std::string_view::npos) return std::nullopt;
180	  const auto window = xml.substr(tag_start, end - tag_start);
181	  std::string needle{name};
182	  needle.append("=\"");
183	  const auto k = window.find(needle);
184	  if (k == std::string_view::npos) return std::nullopt;
185	  const auto v_begin = k + needle.size();
186	  const auto v_end   = window.find('"', v_begin);
187	  if (v_end == std::string_view::npos) return std::nullopt;
188	  return std::string{window.substr(v_begin, v_end - v_begin)};
189	}
190	
191	// Walks a single feature XML body (the contents of one annex), extracting
192	// `<reg name="X" .../>` entries into the map. `next_unnumbered` is updated
193	// with the cumulative count of regs seen across all features so far; an
194	// explicit `regnum="N"` attribute overrides the counter for that one entry
195	// without changing the running total (QEMU's CSR feature uses sparse
196	// regnums, so each subsequent unnumbered entry would be ill-defined - in
197	// practice the CSR feature is the last one parsed).
198	inline void parse_feature_xml(std::string_view xml,
199	                              RegMap& map,
200	                              unsigned& next_unnumbered)
201	{
202	  std::size_t pos = 0;
203	  while (true) {
204	    const auto p = xml.find("<reg ", pos);
205	    if (p == std::string_view::npos) break;
206	    pos = p + 5;
207	    const auto name   = extract_attr(xml, p, "name");
208	    const auto regnum = extract_attr(xml, p, "regnum");
209	    if (!name) continue;
210	    unsigned id = next_unnumbered;
211	    if (regnum) {
212	      try {
213	        id = static_cast<unsigned>(std::stoul(*regnum));
214	      } catch (...) {
215	        id = next_unnumbered++;
216	      }
217	    } else {
218	      ++next_unnumbered;
219	    }
220	    map.insert(*name, id);
221	  }
222	}
223	
224	// Pulls each `<xi:include href="X"/>` href out of target.xml in declaration
225	// order. The order is significant: each annex extends the cumulative
226	// register-number counter from where the previous feature left off.
227	inline auto parse_target_xml(std::string_view xml) -> std::vector<std::string>
228	{
229	  std::vector<std::string> annexes;
230	  std::size_t pos = 0;
231	  while (true) {
232	    const auto p = xml.find("<xi:include", pos);
233	    if (p == std::string_view::npos) break;
234	    if (auto href = extract_attr(xml, p, "href")) annexes.push_back(*href);
235	    pos = p + 11;
236	  }
237	  return annexes;
238	}
239	
240	}  // namespace hybrid::gdbstub
