15	struct DmiBus
16	{
17	  virtual ~DmiBus() = default;
18	  virtual void write(uint8_t reg, uint32_t value) = 0;
19	  virtual auto read(uint8_t reg) -> uint32_t = 0;
20	};
21	
22	class ResumeDriver
23	{
24	public:
25	  // data0/data1/abstractcs/command are defined once in abstract_command.hpp;
26	  // dmcontrol/dmstatus are run-control registers specific to this driver.
27	  static constexpr uint8_t kData0      = kDmiData0;
28	  static constexpr uint8_t kData1      = kDmiData1;
29	  static constexpr uint8_t kDmcontrol  = 0x10;
30	  static constexpr uint8_t kDmstatus   = 0x11;
31	  static constexpr uint8_t kAbstractcs = kDmiAbstractcs;
32	  static constexpr uint8_t kCommand    = kDmiCommand;
33	
34	  static constexpr uint16_t kCsrDpc      = 0x7B1;
35	  static constexpr uint16_t kCsrMstatus  = 0x300;
36	  static constexpr uint16_t kCsrMtvec    = 0x305;
37	  static constexpr uint16_t kCsrMcycle   = 0xB00;
38	  static constexpr uint16_t kCsrMinstret = 0xB02;
39	  static constexpr uint16_t kCsrVstart   = 0x008;
40	  static constexpr uint16_t kCsrVxsat    = 0x009;
41	  static constexpr uint16_t kCsrVxrm     = 0x00A;
42	  static constexpr uint16_t kCsrVcsr     = 0x00F;
43	  static constexpr uint16_t kCsrVtype    = 0xC21;
44	  static constexpr uint16_t kCsrVl       = 0xC20;
45	
46	  static constexpr uint32_t kDmcontrolDmactive  = 1u << 0;
47	  static constexpr uint32_t kDmcontrolResumereq = 1u << 30;
48	  static constexpr uint32_t kDmcontrolHaltreq   = 1u << 31;
49	
50	  static constexpr uint32_t kDmstatusAllhalted    = 1u << 9;
51	  static constexpr uint32_t kDmstatusAllresumeack = 1u << 17;
52	
53	  static constexpr uint32_t kAbstractcsBusy        = hybrid::kAbstractcsBusy;
54	  static constexpr uint32_t kAbstractcsCmderrMask  = hybrid::kAbstractcsCmderrMask;
55	
56	  // mstatus extension-state fields: FS (bits 14:13), VS (bits 10:9).
57	  // "Initial" (01) is the minimal enable the abstract FPR / V writes require.
58	  static constexpr uint64_t kMstatusFsMask    = 0x6000ULL;
59	  static constexpr uint64_t kMstatusFsInitial = 0x2000ULL;
60	  static constexpr uint64_t kMstatusVsMask    = 0x600ULL;
61	  static constexpr uint64_t kMstatusVsInitial = 0x200ULL;
62	
63	  static constexpr unsigned kPollIterations = kDmiPollIterations;
64	
65	  explicit ResumeDriver(DmiBus& bus)
66	      : bus_{bus}
67	  {}
68	
69	  void resume(const hybrid_state_v1& state)
70	  {
71	    if (state.magic != HYBRID_STATE_MAGIC)
72	      throw std::runtime_error("ResumeDriver::resume: bad magic");
73	    if (state.version != HYBRID_STATE_VERSION)
74	      throw std::runtime_error("ResumeDriver::resume: unsupported version");
75	
76	    // dmactive must transition 0->1 in its own write before any other
77	    // DMCONTROL bit is honored (RISC-V Debug Spec).
78	    bus_.write(kDmcontrol, kDmcontrolDmactive);
79	    request_halt();
80	    poll_until_set(bus_, kDmstatus, kDmstatusAllhalted, "ResumeDriver halt");
81	
82	    // mstatus: enable FS / VS so the following FPR / V abstract writes are
83	    // accepted (FS or VS == Off disables the extension and the hart NACKs
84	    // the writes). The drained state.mstatus may legitimately carry FS or
85	    // VS at Off (e.g. an OS context-switched the regs away before the
86	    // trigger fired) -- gating the write on the drained field skips the
87	    // enable and silently NACKs every subsequent FPR / V-CSR write. Always
88	    // write mstatus when either extension is in scope; force-OR Initial
89	    // when the drained field is Off. QEMU2 receives the unmodified drained
90	    // state.mstatus via the gdbstub passthrough, so this enable is local
91	    // to the vsim phase only.
92	    if (state.flags & (HYBRID_FLAG_FP | HYBRID_FLAG_V)) {
93	      uint64_t enable_mstatus = state.mstatus;
94	      if ((state.flags & HYBRID_FLAG_FP) && (enable_mstatus & kMstatusFsMask) == 0)
95	        enable_mstatus |= kMstatusFsInitial;  // FS = Initial
96	      if ((state.flags & HYBRID_FLAG_V)  && (enable_mstatus & kMstatusVsMask) == 0)
97	        enable_mstatus |= kMstatusVsInitial;  // VS = Initial
98	      write_csr_abstract_or_pb(kCsrMstatus, enable_mstatus);
99	    }
100	
101	    // FPR restore (requires mstatus.FS enabled above).
102	    if (state.flags & HYBRID_FLAG_FP) {
103	      for (uint16_t i = 0; i < 32; ++i)
104	        write_64bit_register(regno_fpr(i), state.fpr[i]);
105	    }
106	
107	    // Tier-A V CSR restore (before GPRs: PB fallback uses x5 as scratch;
108	    // the GPR loop overwrites x5 afterward so state is preserved).
109	    if (state.flags & HYBRID_FLAG_V) {
110	      // V data regfile: reload v0..v31 from the shared scratch region via the
111	      // Program Buffer. Runs BEFORE the architectural V-CSR restore below
112	      // because the sweep's own vsetvl (e8/m1) clobbers vtype/vl/vstart, which
113	      // the restore then overwrites with the architectural values. The sweep
114	      // uses x5/x6/x7 as scratch (x7 is the base pointer); the GPR loop below
115	      // restores all three. The wire format reserves HYBRID_VLEN_BYTES_MAX per
116	      // register, so that -- not the runtime vlenb -- is the scratch stride.
117	      pb_v_data_sweep(bus_, kVScratchGpa, HYBRID_VLEN_BYTES_MAX, state.vlenb,
118	                      /*load=*/true);
119	
120	      // Tier-B: vtype+vl via vsetvl x0,x5,x6 in PB.
121	      // Direct csrrw to vtype sets vill; vl is read-only. Stage operands in
122	      // scratch GPRs x5(vl) and x6(vtype) then let vsetvl set both atomically.
123	      // x5/x6 are overwritten by the GPR loop below, so no leakage.
124	      write_64bit_register(regno_gpr(5), state.vl);
125	      write_64bit_register(regno_gpr(6), state.vtype);
126	      const std::array<uint32_t, 1> pb_vsetvl = { encode_vsetvl(0, 5, 6) };
127	      exec_progbuf(bus_, std::span<const uint32_t>{pb_vsetvl});
128	      // vstart must come AFTER vsetvl: vsetvl resets vstart to 0.
129	      write_csr_abstract_or_pb(kCsrVstart, state.vstart);
130	      write_csr_abstract_or_pb(kCsrVxsat,  state.vxsat);
131	      write_csr_abstract_or_pb(kCsrVxrm,   state.vxrm);
132	      write_csr_abstract_or_pb(kCsrVcsr,   state.vcsr);
133	    }
134	
135	    // GPRs + DPC (after V CSRs so PB scratch x5 is safe to overwrite).
136	    for (uint16_t i = 1; i < 32; ++i)
137	      write_64bit_register(regno_gpr(i), state.gpr[i]);
138	    write_64bit_register(regno_csr(kCsrDpc), state.pc);
139	
140	    write_csr_tolerant(kCsrMtvec, state.mtvec);
141	
142	    // F-T2.4: restore mcycle/minstret so the vsim phase continues counting
143	    // from QEMU1's drain value. Without this, vsim's local counter starts
144	    // at zero and any cycles spent inside the ROI vanish at the QEMU2
145	    // boundary. PB fallback uses x5 as scratch; safe to overwrite here as
146	    // the GPR loop already ran.
147	    write_csr_abstract_or_pb(kCsrMcycle,   state.mcycle);
148	    write_csr_abstract_or_pb(kCsrMinstret, state.minstret);
149	
150	    clear_cmderr_if_set();
151	    request_resume();
152	    poll_until_set(bus_, kDmstatus, kDmstatusAllresumeack,
153	                   "ResumeDriver resume");
154	  }
155	
156	private:
157	  void request_halt()
158	  {
159	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolHaltreq);
160	  }
161	
162	  void request_resume()
163	  {
164	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolResumereq);
165	  }
166	
167	  void write_64bit_register(uint16_t regno, uint64_t value)
168	  {
169	    write_register_abstract(bus_, regno, value);
170	  }
171	
172	  // Abstract-first CSR write with Program Buffer fallback.
173	  // Tries an abstract register write; if the DM signals cmderr, clears it,
174	  // stages the value in scratch_gpr via abstract GPR write, then executes a
175	  // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
176	  // to x5 (t0) which the GPR restore loop overwrites later.
177	  void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
178	                                 uint8_t scratch_gpr = 5)
179	  {
180	    write_64bit_register(regno_csr(csr), value);
181	    if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
182	    bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
183	    write_64bit_register(regno_gpr(scratch_gpr), value);
184	    const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
185	    exec_progbuf(bus_, std::span<const uint32_t>{pb});
186	  }
187	
188	  // Write a CSR-addressable register and clear any cmderr the DM raised.
189	  // Used for CSRs whose abstract-access support may be implementation
190	  // dependent; a missing CSR mirrors as a no-op rather than blocking the
191	  // remaining writes.
192	  void write_csr_tolerant(uint16_t csr, uint64_t value)
193	  {
194	    write_64bit_register(regno_csr(csr), value);
195	    clear_cmderr_if_set();
196	  }
197	
198	  // abstractcs.cmderr is sticky per the Debug Spec - a subsequent command
199	  // is rejected until the bits are W1C-cleared. We tolerate per-register
200	  // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
201	  // error before resuming so the hart isn't left in a stuck state.
202	  // B17: record the last observed non-zero cmderr and a clear count so a
203	  // partially-broken restore is observable via the public accessors
204	  // instead of silently swallowed.
205	  void clear_cmderr_if_set()
206	  {
207	    const auto status = bus_.read(kAbstractcs);
208	    const auto code = (status & kAbstractcsCmderrMask) >> 8;
209	    if (code != 0u) {
210	      last_observed_cmderr_ = code;
211	      ++cmderr_clear_count_;
212	      bus_.write(kAbstractcs, kAbstractcsCmderrMask);
213	    }
214	  }
215	
216	  DmiBus& bus_;
217	  uint32_t last_observed_cmderr_ = 0;
218	  uint64_t cmderr_clear_count_   = 0;
219	
220	public:
221	  // B17: diagnostic side channel. Non-zero last_observed_cmderr() means
222	  // at least one abstract write tripped a sticky cmderr the restore
223	  // tolerated by clearing. cmderr_clear_count() is the total number of
224	  // such clears across all calls into clear_cmderr_if_set() this run.
225	  auto last_observed_cmderr() const -> uint32_t { return last_observed_cmderr_; }
226	  auto cmderr_clear_count() const -> uint64_t   { return cmderr_clear_count_; }
227	};
228	
229	// Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
230	// via an Abstract Command. Halts-and-reads contract: caller must have the
231	// hart in the halted state. Shared by StateDrain (drain at exit), and by
232	// MeasureStartSnapshot (snapshot at K-th retire). If abstractcs.cmderr
233	// goes sticky after the command, the helper clears it and reports 0
234	// rather than blocking the caller -- a missing CSR mirrors as zero
235	// instead of corrupting the adjacent field.
236	inline auto read_register_64(DmiBus& bus, uint16_t regno,
237	                             const char* poll_label = "read_register_64")
238	  -> uint64_t
239	{
240	  using RD = ResumeDriver;
241	  bus.write(RD::kCommand,
242	            access_register_command(regno, AarSize::Bits64, /*write=*/false));
243	  poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
244	  const auto status = bus.read(RD::kAbstractcs);
245	  if ((status & RD::kAbstractcsCmderrMask) != 0u) {
246	    bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
247	    return 0u;
248	  }
249	  const uint64_t lo = bus.read(RD::kData0);
250	  const uint64_t hi = bus.read(RD::kData1);
251	  return lo | (hi << 32);
252	}
