1	// StateDrain halts the hart via the Debug Module and populates a
2	// hybrid_state_v1 with the architectural register file. Reuses
3	// ResumeDriver's DM register constants and DmiBus interface.
4	
5	#pragma once
6	
7	#include "hybrid/abstract_command.hpp"
8	#include "hybrid/dmi_poll.hpp"
9	#include "hybrid/resume_driver.hpp"
10	#include "hybrid/state_abi.h"
11	#include "hybrid/v_regfile_xfer.hpp"
12	
13	#include <algorithm>
14	#include <cstdint>
15	
16	namespace hybrid
17	{
18	
19	class StateDrain
20	{
21	public:
22	  using RD = ResumeDriver;
23	
24	  explicit StateDrain(DmiBus& bus)
25	      : bus_{bus}
26	  {}
27	
28	  // F16: stash the warmup-window snapshot (mcycle, minstret captured K
29	  // retires after vsim entry). Both drain() and drain_with_passthrough()
30	  // copy these into the returned state. Zero when MeasureStartSnapshot
31	  // never fired (K=0 or workload exited inside the warmup window).
32	  void set_warmup_snapshot(uint64_t mcycle, uint64_t minstret)
33	  {
34	    warmup_mcycle_   = mcycle;
35	    warmup_minstret_ = minstret;
36	  }
37	
38	  // Drain x1..x31 + PC. FP/CSR/V slots remain zero; merge them in via
39	  // drain_with_passthrough when the QEMU 1 snapshot is available.
40	  auto drain() -> hybrid_state_v1
41	  {
42	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
43	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
44	    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllhalted,
45	                   "StateDrain halt");
46	
47	    hybrid_state_v1 state{};
48	    state.magic   = HYBRID_STATE_MAGIC;
49	    state.version = HYBRID_STATE_VERSION;
50	    state.flags   = HYBRID_FLAG_RV64;
51	    state.priv    = 3;
52	
53	    for (uint16_t i = 1; i < 32; ++i)
54	      state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");
55	
56	    state.pc = read_register_64(bus_, regno_csr(RD::kCsrDpc), "StateDrain DPC");
57	    state.mcycle_at_measure_start   = warmup_mcycle_;
58	    state.minstret_at_measure_start = warmup_minstret_;
59	    return state;
60	  }
61	
62	  // Returns the input snapshot with x1..x31 and PC overwritten by a fresh
63	  // DM read. When HYBRID_FLAG_FP is set, also freshly reads f0..f31 so
64	  // post-vsim FP modifications are captured (otherwise the stale QEMU 1
65	  // snapshot leaks through to QEMU 2). When HYBRID_FLAG_V is set, also
66	  // freshly reads the six V CSRs (vstart/vxsat/vxrm/vcsr/vtype/vl); vlenb
67	  // and vreg remain pass-through (read-only / too large for DM).
68	  // mcycle/minstret are always refreshed (F-T2.4): the vsim phase's
69	  // contribution would otherwise be discarded as the passthrough preserves
70	  // QEMU1's pre-handoff value.
71	  auto drain_with_passthrough(const hybrid_state_v1& input) -> hybrid_state_v1
72	  {
73	    auto state       = input;
74	    const auto fresh = drain();
75	    std::copy(std::begin(fresh.gpr) + 1, std::end(fresh.gpr),
76	              std::begin(state.gpr) + 1);
77	    state.pc = fresh.pc;
78	
79	    if (input.flags & HYBRID_FLAG_FP) {
80	      for (uint16_t i = 0; i < 32; ++i)
81	        state.fpr[i] = read_register_64(bus_, regno_fpr(i), "StateDrain FPR");
82	    }
83	
84	    if (input.flags & HYBRID_FLAG_V) {
85	      state.vstart = read_register_64(bus_, regno_csr(RD::kCsrVstart));
86	      state.vxsat  = read_register_64(bus_, regno_csr(RD::kCsrVxsat));
87	      state.vxrm   = read_register_64(bus_, regno_csr(RD::kCsrVxrm));
88	      state.vcsr   = read_register_64(bus_, regno_csr(RD::kCsrVcsr));
89	      state.vtype  = read_register_64(bus_, regno_csr(RD::kCsrVtype));
90	      state.vl     = read_register_64(bus_, regno_csr(RD::kCsrVl));
91	    }
92	
93	    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle));
94	    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret));
95	
96	    // V data regfile: dump v0..v31 to the shared scratch region via the
97	    // Program Buffer LAST -- after every architectural read above -- so the
98	    // sweep's clobbers (vtype/vl/vstart, x5/x6/x7) and its counter increments
99	    // cannot corrupt the values already captured. The simulator's
100	    // read_v_from_scratch then lifts the scratch bytes into state.vreg[].
101	    // Stride is HYBRID_VLEN_BYTES_MAX (the wire-format per-register span).
102	    if (input.flags & HYBRID_FLAG_V)
103	      pb_v_data_sweep(bus_, kVScratchGpa, HYBRID_VLEN_BYTES_MAX, input.vlenb,
104	                      /*load=*/false);
105	
106	    state.mcycle_at_measure_start   = warmup_mcycle_;
107	    state.minstret_at_measure_start = warmup_minstret_;
108	    return state;
109	  }
110	
111	private:
112	  DmiBus& bus_;
113	  uint64_t warmup_mcycle_   = 0;  // F16: zero when warmup boundary never fired
114	  uint64_t warmup_minstret_ = 0;
115	};
