namespace hybrid {

// Phase-3 orchestrator: spawn QEMU2, restore state, continue
void qemu_handback(const hybrid_state_v1& state,
                  const std::string& qemu_binary,
                  const std::string& mmap_path,
                  uint64_t mmap_size,
                  int gdb_port)  // or auto-pick via pick_free_port()
